  "refcases_p1_detol_subtitle": "Zaltbommel, nieuwbouw",
  "refcases_p1_detol_summary": "Stijgende bouwkosten zetten druk op de businesscase. De partners zochten een technisch gelijkwaardige maar betaalbaardere oplossing. Dankzij de bestaande samenwerking met Preworxs en onze prefab techniekruimte is gekozen voor Qvantum: minimale werkzaamheden op locatie, repeteerbaar per blok en een scherpere totaalprijs.",
