  "refcases_p10_de_heinzvondheiden_quote": "Buiten opgestelde warmtepompen worden vaak beperkt door geluidsregels, zeker bij een hoge bebouwingsdichtheid. Daarom is de ventilatielucht warmtepomp van Qvantum hier ideaal.",
