  "refcases_title": "Dit is wat wij doen.",
  "story_s0_head_left_below": "Industrialisering",
  "story_s0_head_left": "Warmtepomp industrie",
  "story_s0_head_right_below": "Energiesystemen",
  "story_s0_head_right": "Digitalisering",
  "story_s0_subtitle": "Verbinden van industrieën creëert een unieke basis. Dat is Qvantum.",
  "story_s0_title": "Een duurzame toekomst",
  "story_s1_details1": "Elke warmtepomp is een bouwsteen van een stabiele, klimaatvriendelijke energievoorziening.",
  "story_s1_details2": "Veel warmtepompen samen vormen intelligente warmtenetten, schaalbaar tot stadsniveau",
  "story_s1_details3": "Ontworpen om in grote steden duizenden mensen van warmte te voorzien.",
  "story_s1_details4": "Sterke partners helpen Qvantum de warmtetransitie in Europa vorm te geven.",
  "story_s1_icontext_1": "Oprichting Qvantum",
  "story_s1_icontext_2": "Fusie huidig Qvantum",
  "story_s1_icontext_3": "Fabriek Åstorp",
  "story_s1_icontext_4": "Qvantum Nederland",
  "story_s1_icontext_5": "Mega fabriek Hongarije",
  "story_s1_icontext_6": "Introductie residentiële warmtepompen",
  "story_s1_keyword1": "Nieuwe manier van denken",
  "story_s1_keyword2": "State of the art technologie",
  "story_s1_keyword3": "Impact op grote schaal",
  "story_s1_keyword4": "Samenwerking als versneller",
  "story_s1_subtitle": "Een fossielvrije toekomst voor iedereen, dat vraagt om écht andere energiesystemen en warmtepompen. Qvantum: new energy era.",
  "story_s1_title": "Onze visie",
  "story_s2_bullets_1_details": "Innovatie en marktintroducties: betrouwbare supply chain als strategie",
  "story_s2_bullets_1_title": "Åstorp: innovatie",
  "story_s2_bullets_2_details": "Schaalbaarheid en hoge efficiëntiele: kwaliteit en herhaalbaarheid",
  "story_s2_bullets_2_title": "Nyíregyháza: schaalbaar",
  "story_s2_bullets_3_details": "Snel, innovatief en schaalbaar: door deze organisatiestructuur en de twee vestigingen kan Qvantum snel en innovatief handelen, terwijl het bedrijf tegelijk kan opschalen en hoge efficiëntie en productiviteit behaalt.",
  "story_s2_bullets_3_title": "Samen: sterker",
  "story_s2_fac1": "Åstorp, Zweden",
  "story_s2_fac1details_2": "Productiecapaciteit: 50.000 stuks",
  "story_s2_fac1details": "Productieoppervlakte: 7.500 m2",
  "story_s2_fac2": "Nyíregyháza, Hongarije",
  "story_s2_fac2details_2": "Productiecapaciteit: > 300.000 stuks",
  "story_s2_fac2details": "Productieoppervlakte: 68.500 m2",
  "story_s2_title": "Productie & schaalbaarheid",
  "story_s3_adress1": "Qvantum Nederland",
  "story_s3_adress2": "Jean Monnetpark, 7336 BA Apeldoorn",
  "story_s3_adress3": "qvantum.com/nl",
  "story_s3_bullet_1": "Dochteronderneming",
  "story_s3_bullet_2": "Distributeurs",
  "story_s3_bullet_3": "Qvantum-fabriek",
  "story_s3_subtitle": "met dochterondernemingen in het Verenigd Koninkrijk, Duitsland, Nederland, Polen, Hongarije, Frankrijk en Oostenrijk.",
  "story_s3_title": "Hier zijn wij gevestigd",
  "story_s4_details1": "Wereldklasse ontwerp, datagedreven ontwikkeling en topcomponenten - ontworpen voor topprestaties en lange levensduur.",
  "story_s4_details2": "Natuurlijk, toekomstvast en zonder extra ventilatie-eisen; snel en zorgeloos te plaatsen.",
  "story_s4_details3": "Laadt warmte bij lage (groene) stroomprijzen en levert op pieken — comfort blijft gelijk, kosten en netlast omlaag.",
  "story_s4_details4": "Koelen waar de bron dat toelaat, met zeer lage geluidsniveaus; hygiënisch tapwater via warmtewisselaar.",
  "story_s4_details5": "Software-updates op afstand, diagnose op afstand en vlootbeheer, plus onze ontwerptool voor snelle specificatie.",
  "story_s4_details6": "Laagtemperatuur als uitgangspunt, naadloos op (mini)bronnetten; lage netimpact.",
  "story_s4_details7": "Eén gestandaardiseerd platform voor efficiënte productie, snelle installatie, eenvoudig onderhoud en scherpe projectprijzen.",
  "story_s4_keyword1": "Topklasse techniek & materialen",
  "story_s4_keyword2": "R290 met lage vulling & plug-and-play",
  "story_s4_keyword3": "Slim en voordelig: flexibel + thermische batterij",
  "story_s4_keyword4": "Comfortkoeling, fluisterstil & vers tapwater",
  "story_s4_keyword5": "Toekomstvast digitaal systeem",
  "story_s4_keyword6": "Netbewust & geschikt voor ZLT-netten",
  "story_s4_keyword7": "Maximale modulariteit (±90% onderdeelgelijkheid)",
  "story_s4_subtitle": "Connected, modulair en netbewust: voor projecten én collectieve systemen",
  "story_s4_title": "Geen gewone warmtepomp",
  "story_s5_details2": "een van de grootste veroorzakers van uitstoot",
  "story_s5_details3_1": "van de energie is nodig voor verwarmen en koelen",
  "story_s5_details3_2": "hiervan komt nog van fossiele bronnen",
  "story_s5_details3_3": "van energieverbruik in onze woningen gaat naar verwarming en heet water",
  "story_s5_details4": "een warmtepomp is de duurzame oplossing hiervoor",
  "story_s5_details5_1": "besparing",
  "story_s5_details6": "Qvantum: new energy era",
  "story_s5_keyword1": "& de gebouwde omgeving",
  "story_s5_keyword2": "emmissie wereldwijd wordt veroorzaakt door de gebouwde omgeving.",
  "story_s5_keyword3": "ons energieverbruik thuis",
  "story_s5_keyword4": "verduurzaming is nodig, en warmte, koeling en heet water zijn de sleutel.",
  "story_s5_keyword5": "onze bijdrage aan netzero",
  "story_s5_keyword6": "de warmtepomp levert een grote bijdrage aan decarbonisatie.",
  "story_s5_subtitle": "de impact van warmtepompen",
  "story_s5_title": "Decarbonisatie",
  "story_s6_body": "Erkend voor baanbrekende innovatie in energieflexibiliteit en geselecteerd uit honderden wereldwijde inzendingen door BloombergNEF-experts. Eerdere pioneers zijn Tesla, NIO, ChargePoint, Form Energy en WeaveGrid.",
  "story_s6_subtitle": "Winnaar – Flattening the Duck Curve",
