  "story_s3_title": "Our locations",
  "story_s4_details1": "World-class design, data-driven development and high quality components – designed for durability and efficiency.",
  "story_s4_details2": "Natural, future-proof and without additional ventilation requirements; quick and easy to install.",
  "story_s4_details3": "Charges heat when electricity prices are low and delivers at peak times — comfort remains the same, costs and grid load are reduced.",
  "story_s4_details4": "Cooling where the source allows, with very low noise levels; instantaneous tap water via heat exchanger.",
  "story_s4_details5": "Remote software updates, remote diagnostics and fleet management, plus our design tool for quick specification.",
  "story_s4_details6": "Low temperature as a starting point, seamlessly integrated into (mini) source networks; low network impact.",
  "story_s4_details7": "One standardised platform for efficient production, quick installation, easy maintenance and competitive project prices.",
