  "story_s0_subtitle": "Die Verbindung von Branchen schafft eine einzigartige Grundlage. Das ist Qvantum.",
  "story_s0_title": "Die Zukunft ist nachhaltig",
  "story_s1_details1": "Jede Wärmepumpe ist ein Baustein für eine stabile, klimafreundliche Energieversorgung.",
  "story_s1_details2": "Viele Wärmepumpen verbinden sich zu einem intelligenten Wärmenetz. Skaliert bis zur Stadt.",
  "story_s1_details3": "Entwickelt, um Tausende von Menschen in Großstädten mit Wärme zu versorgen.",
  "story_s1_details4": "Starke Partner helfen Qvantum dabei, die Wärmewende in Europa zu gestalten.",
  "story_s1_icontext_1": "Gründung von Qvantum",
  "story_s1_icontext_2": "Vom Einzelprodukt zum System",
  "story_s1_icontext_3": "Werk Åstorp",
  "story_s1_icontext_4": "Qvantum Deutschland",
