  "story_s1_keyword2": "Modernste Technologie",
  "story_s1_keyword3": "Auswirkungen in großem Maßstab",
  "story_s1_keyword4": "Zusammenarbeit als Beschleuniger",
  "story_s1_subtitle": "Fossilfreie Städte brauchen neue Energiesysteme.\\n Und Wärmepumpen, die dafür gemacht sind.",
  "story_s1_title": "Unsere Vision",
  "story_s2_bullets_1_details": "Innovation und Markteinführungen: Zuverlässige Lieferkette als Strategie",
  "story_s2_bullets_1_title": "Åstorp: Innovation",
  "story_s2_bullets_2_details": "Skalierbarkeit und hohe Effizienz: Qualität und Wiederholbarkeit",
  "story_s2_bullets_2_title": "Nyíregyháza: Skalierbarkeit",
  "story_s2_bullets_3_details": "Schnell, innovativ und skalierbar: Dank dieser Organisationsstruktur und den beiden Standorten kann Qvantum schnell und innovativ handeln und gleichzeitig skalieren und eine hohe Effizienz und Produktivität erzielen.",
  "story_s2_bullets_3_title": "Gemeinsam: stärker",
