  "story_s3_subtitle": "mit Tochtergesellschaften in Großbritannien, Deutschland, den Niederlanden, Polen, Ungarn, Frankreich und Österreich.",
  "story_s3_title": "Hier sind wir aktiv",
  "story_s4_details1": "Weltklasse-Design, datengesteuerte Entwicklung und Spitzenkomponenten – entwickelt für Spitzenleistung und lange Lebensdauer.",
  "story_s4_details2": "Natürlich & zukunftssicher. Keine Leckagenüberwachung oder spezielle Lüftungsmaßnahmen erforderlich, einfache Planung und Installation",
  "story_s4_details3": "Lädt Wärme bei niedrigen (grünen) Strompreisen und liefert bei Spitzenlasten – der Komfort bleibt gleich, Kosten und Netzbelastung sinken.",
  "story_s4_details4": "Kühlen, wo es die Quelle zulässt, mit sehr niedrigen Geräuschpegeln; hygienisches Leitungswasser über Wärmetauscher.",
  "story_s4_details5": "Fern-Software-Updates, Ferndiagnose und Flottenmanagement sowie unser Design-Tool für schnelle Spezifikationen.",
  "story_s4_details6": "Niedrige Temperaturen als Ausgangspunkt, nahtlos in (Mini-)Quellennetze integrierbar; geringe Netzbelastung.",
  "story_s4_details7": "Eine standardisierte Plattform für effiziente Produktion, schnelle Installation, einfache Wartung und wettbewerbsfähige Projektpreise.",
  "story_s4_keyword1": "Erstklassige Technik und Materialien",
  "story_s4_keyword2": "R290 mit geringer Füllung & Plug-and-Play",
  "story_s4_keyword3": "Intelligent und kostengünstig: flexibel + thermische Batterie",
  "story_s4_keyword4": "Komfortkühlung, flüsterleise & frisches Leitungswasser",
  "story_s4_keyword5": "Zukunftssicheres digitales System",
  "story_s4_keyword6": "Netzbewusst und geeignet für ZLT-Netze",
  "story_s4_keyword7": "Maximale Modularität (±90 % Teilegleichheit)",
  "story_s4_subtitle": "Vernetzt, modular und netzwerkbewusst: für Projekte und kollektive Systeme",
  "story_s4_title": "Keine Wärmepumpe wie jede andere",
  "story_s5_details2": "Einer der größten Verursacher von Emissionen",
  "story_s5_details3_1": "der Energie wird für Heizung und Kühlung benötigt",
  "story_s5_details3_2": "davon stammt noch aus fossilen Quellen",
  "story_s5_details3_3": "des Energieverbrauchs in unseren Haushalten entfällt auf Heizung und Warmwasser",
  "story_s5_details4": "Eine Wärmepumpe ist die nachhaltige Lösung dafür",
  "story_s5_details5_1": "Einsparung",
  "story_s5_details6": "Qvantum: Wärmepumpe.Einfach.Anders",
  "story_s5_keyword1": "und die bebaute Umwelt",
  "story_s5_keyword2": "Die weltweiten Emissionen werden durch die bebaute Umwelt verursacht.",
  "story_s5_keyword3": "Unser Energieverbrauch zu Hause",
  "story_s5_keyword4": "Nachhaltigkeit ist notwendig, und Wärme, Kühlung und Warmwasser sind der Schlüssel dazu.",
  "story_s5_keyword5": "Unser Beitrag zu Net Zero",
  "story_s5_keyword6": "Die Wärmepumpe leistet einen großen Beitrag zur Dekarbonisierung.",
  "story_s5_subtitle": "Die Auswirkungen von Wärmepumpen",
  "story_s5_title": "Dekarbonisierung",
  "story_s6_body": "Ausgezeichnet für bahnbrechende Innovation in der Energieflexibilität, ausgewählt aus Hunderten Bewerbungen weltweit durch BloombergNEF-Experten. Frühere Pioneers: Tesla, NIO, ChargePoint, Form Energy und WeaveGrid.",
  "story_s6_subtitle": "Gewinner – Flattening the Duck Curve",
