  "story_s0_subtitle": "Att koppla samman industrier skapar en unik bas. Det är Qvantum.",
  "story_s0_title": "En hållbar framtid",
  "story_s1_details1": "Varje värmepump är en byggsten i en stabil, klimatvänlig energiförsörjning.",
  "story_s1_details2": "Många värmepumpar tillsammans bildar intelligenta värmenät, skalbara till stadsnivå.",
  "story_s1_details3": "Utformad för att förse tusentals människor i stora städer med värme.",
  "story_s1_details4": "Starka partners hjälper Qvantum att forma värmeomställningen i Europa.",
