  "story_s1_subtitle": "En fossilfri framtid för alla kräver helt nya energisystem och värmepumpar. Qvantum: en ny energitidsålder.",
  "story_s1_title": "Vår vision",
  "story_s2_bullets_1_details": "Innovation och marknadsintroduktioner: pålitlig leveranskedja som strategi",
  "story_s2_bullets_1_title": "Åstorp: innovation",
  "story_s2_bullets_2_details": "Skalbarhet och hög effektivitet: kvalitet och repeterbarhet",
  "story_s2_bullets_2_title": "Nyíregyháza: skalbarhet",
  "story_s2_bullets_3_details": "Snabbt, innovativt och skalbart: tack vare denna organisationsstruktur och de två anläggningarna kan Qvantum agera snabbt och innovativt, samtidigt som företaget kan skala upp och uppnå hög effektivitet och produktivitet.",
  "story_s2_bullets_3_title": "Tillsammans: starkare",
