  "story_s3_subtitle": "med dotterbolag i Storbritannien, Tyskland, Nederländerna, Polen, Ungern, Frankrike och Österrike.",
  "story_s3_title": "Här finns vi",
  "story_s4_details1": "Världsklassig design, datadriven utveckling och toppkomponenter – utformade för högsta prestanda och lång livslängd.",
  "story_s4_details2": "Naturligt, framtidssäkert och utan extra ventilationskrav; snabbt och enkelt att installera.",
  "story_s4_details3": "Laddar värme vid låga (gröna) elpriser och levererar vid toppar – komforten förblir densamma, kostnaderna och nätbelastningen minskar.",
  "story_s4_details4": "Kylning där källan tillåter det, med mycket låga ljudnivåer; hygieniskt kranvatten via värmeväxlare.",
  "story_s4_details5": "Fjärruppdateringar av programvara, fjärrdiagnostik och flottförvaltning, plus vårt designverktyg för snabb specifikation.",
  "story_s4_details6": "Lågtemperatur som utgångspunkt, sömlöst på (mini)källnät; låg nätpåverkan.",
  "story_s4_details7": "En standardiserad plattform för effektiv produktion, snabb installation, enkelt underhåll och konkurrenskraftiga projektpriser.",
  "story_s4_keyword1": "Teknik och material i toppklass",
  "story_s4_keyword2": "R290 med låg fyllning och plug-and-play",
  "story_s4_keyword3": "Smart och ekonomiskt: flexibelt + termisk batteri",
  "story_s4_keyword4": "Komfortkylning, tystgående och färskt kranvatten",
  "story_s4_keyword5": "Framtidssäkert digitalt system",
  "story_s4_keyword6": "Nätmedvetet och lämpligt för ZLT-nät",
  "story_s4_keyword7": "Maximal modularitet (±90 % komponentlikhet)",
  "story_s4_subtitle": "Ansluten, modulär och nätmedveten: för projekt och kollektiva system",
  "story_s4_title": "Ingen vanlig värmepump",
  "story_s5_details2": "En av de största orsakerna till utsläpp",
  "story_s5_details3_1": "av energin behövs för uppvärmning och kylning",
  "story_s5_details3_2": "av detta kommer fortfarande från fossila källor",
  "story_s5_details3_3": "av energiförbrukningen i våra hem går till uppvärmning och varmvatten",
  "story_s5_details4": "En värmepump är den hållbara lösningen för detta",
  "story_s5_details5_1": "besparing",
  "story_s5_details6": "Qvantum: en ny energitidsålder",
  "story_s5_keyword1": "& den bebyggda miljön",
