  "refcases_title": "To właśnie robimy.",
  "story_s0_head_left_below": "Industrializacja",
  "story_s0_head_left": "Przemysł pomp ciepła",
  "story_s0_head_right_below": "Systemy energetyczne",
  "story_s0_head_right": "Cyfryzacja",
  "story_s0_subtitle": "Łączenie branż tworzy wyjątkową podstawę. To właśnie Qvantum.",
  "story_s0_title": "Zrównoważona przyszłość",
  "story_s1_details1": "Każda pompa ciepła jest elementem składowym stabilnego, przyjaznego dla klimatu systemu zaopatrzenia w energię.",
  "story_s1_details2": "Wiele pomp ciepła tworzy inteligentne sieci ciepłownicze, które można skalować do poziomu miasta.",
  "story_s1_details3": "Zaprojektowane z myślą o dostarczaniu ciepła tysiącom ludzi w dużych miastach.",
  "story_s1_details4": "Silni partnerzy pomagają Qvantum kształtować transformację energetyczną w Europie.",
  "story_s1_icontext_1": "Założenie firmy Qvantum",
  "story_s1_icontext_2": "Fuzja obecnego Qvantum",
  "story_s1_icontext_3": "Fabryka Åstorp",
  "story_s1_icontext_4": "Qvantum Holandia",
  "story_s1_icontext_5": "Mega fabryka na Węgrzech",
  "story_s1_icontext_6": "Wprowadzenie pomp ciepła do użytku domowego",
  "story_s1_keyword1": "Nowy sposób myślenia",
  "story_s1_keyword2": "Najnowocześniejsza technologia",
  "story_s1_keyword3": "Wpływ na dużą skalę",
  "story_s1_keyword4": "Współpraca jako czynnik przyspieszający",
  "story_s1_subtitle": "Przyszłość bez paliw kopalnych dla wszystkich wymaga zupełnie innych systemów energetycznych i pomp ciepła. Qvantum: nowa era energii.",
  "story_s1_title": "Nasza wizja",
  "story_s2_bullets_1_details": "Innowacje i wprowadzanie produktów na rynek: niezawodny łańcuch dostaw jako strategia",
  "story_s2_bullets_1_title": "Åstorp: innowacje",
  "story_s2_bullets_2_details": "Skalowalność i wysoka wydajność: jakość i powtarzalność",
  "story_s2_bullets_2_title": "Nyíregyháza: skalowalność",
  "story_s2_bullets_3_details": "Szybkość, innowacyjność i skalowalność: dzięki tej strukturze organizacyjnej i dwóm oddziałom firma Qvantum może działać szybko i innowacyjnie, jednocześnie zwiększając skalę działalności i osiągając wysoką wydajność i produktywność.",
  "story_s2_bullets_3_title": "Razem: silniejsi",
  "story_s2_fac1": "Åstorp, Szwecja",
  "story_s2_fac1details_2": "Zdolność produkcyjna: 50 000 sztuk",
  "story_s2_fac1details": "Powierzchnia produkcyjna: 7500 m2",
  "story_s2_fac2": "Nyíregyháza, Węgry",
  "story_s2_fac2details_2": "Zdolność produkcyjna: > 300 000 sztuk",
  "story_s2_fac2details": "Powierzchnia produkcyjna: 68 500 m2",
  "story_s2_title": "Produkcja i skalowalność",
  "story_s3_adress1": "Qvantum Holandia",
  "story_s3_adress2": "Jean Monnetpark, 7336 BA Apeldoorn",
  "story_s3_adress3": "qvantum.com/nl",
  "story_s3_bullet_1": "Spółka zależna",
  "story_s3_bullet_2": "Dystrybutorzy",
  "story_s3_bullet_3": "Fabryka Qvantum",
  "story_s3_subtitle": "z oddziałami w Wielkiej Brytanii, Niemczech, Holandii, Polsce, na Węgrzech, we Francji i Austrii.",
  "story_s3_title": "Oto nasze lokalizacje",
  "story_s4_details1": "Światowej klasy projekt, rozwój oparty na danych i najwyższej jakości komponenty – zaprojektowane z myślą o najwyższej wydajności i długiej żywotności.",
  "story_s4_details2": "Naturalny, przyszłościowy i bez dodatkowych wymagań wentylacyjnych; szybki i łatwy w montażu.",
  "story_s4_details3": "Ładuje ciepło przy niskich (ekologicznych) cenach energii elektrycznej i dostarcza je w okresach szczytowego zapotrzebowania — komfort pozostaje taki sam, a koszty i obciążenie sieci spadają.",
  "story_s4_details4": "Chłodzenie tam, gdzie pozwala na to źródło, przy bardzo niskim poziomie hałasu; higieniczna woda pitna z kranu dzięki wymiennikowi ciepła.",
  "story_s4_details5": "Zdalne aktualizacje oprogramowania, zdalna diagnostyka i zarządzanie flotą, a także nasze narzędzie projektowe do szybkiej specyfikacji.",
  "story_s4_details6": "Niska temperatura jako punkt wyjścia, płynna integracja z (mini) sieciami źródłowymi; niewielki wpływ na sieć.",
  "story_s4_details7": "Jedna znormalizowana platforma zapewniająca wydajną produkcję, szybką instalację, łatwą konserwację i konkurencyjne ceny projektów.",
  "story_s4_keyword1": "Najwyższej klasy technologia i materiały",
  "story_s4_keyword2": "R290 z niskim wypełnieniem i funkcją plug-and-play",
  "story_s4_keyword3": "Inteligentne i ekonomiczne: elastyczne + akumulator termiczny",
  "story_s4_keyword4": "Komfortowe chłodzenie, cicha praca i świeża woda z kranu",
  "story_s4_keyword5": "Przyszłościowy system cyfrowy",
  "story_s4_keyword6": "Świadomość sieciowa i przystosowanie do sieci ZLT",
  "story_s4_keyword7": "Maksymalna modułowość (±90% identyczności części)",
  "story_s4_subtitle": "Połączone, modułowe i energooszczędne: do projektów i systemów zbiorowych",
  "story_s4_title": "Niezwykła pompa ciepła",
  "story_s5_details2": "jednym z największych źródeł emisji",
  "story_s5_details3_1": "energii jest potrzebna do ogrzewania i chłodzenia",
  "story_s5_details3_2": "z czego pochodzi z paliw kopalnych",
  "story_s5_details3_3": "zużycia energii w naszych domach przeznacza się na ogrzewanie i ciepłą wodę",
  "story_s5_details4": "Pompa ciepła jest zrównoważonym rozwiązaniem w tym zakresie",
  "story_s5_details5_1": "oszczędności",
  "story_s5_details6": "Qvantum: nowa era energii",
  "story_s5_keyword1": "i środowisko budowlane",
  "story_s5_keyword2": "Emisje na całym świecie są spowodowane przez środowisko budowlane.",
  "story_s5_keyword3": "nasze zużycie energii w domu",
  "story_s5_keyword4": "konieczne jest zwiększenie zrównoważonego rozwoju, a kluczem do tego są ogrzewanie, chłodzenie i ciepła woda.",
  "story_s5_keyword5": "nasz wkład w osiągnięcie zerowej emisji netto",
  "story_s5_keyword6": "Pompa ciepła w znacznym stopniu przyczynia się do dekarbonizacji.",
  "story_s5_subtitle": "Wpływ pomp ciepła",
  "story_s5_title": "Dekarbonizacja",
  "story_s6_body": "Wyróżnienie za przełomową innowację w elastyczności energetycznej, wybrane spośród setek zgłoszeń z całego świata przez ekspertów BloombergNEF. Wcześniejsi pionierzy: Tesla, NIO, ChargePoint, Form Energy i WeaveGrid.",
  "story_s6_subtitle": "Zwycięzca – Flattening the Duck Curve",
