  "story_s0_title": "Un avenir durable",
  "story_s1_details1": "Chaque pompe à chaleur est un élément constitutif d'un approvisionnement énergétique stable et respectueux du climat.",
  "story_s1_details2": "De nombreuses pompes à chaleur réunies forment des réseaux de chaleur intelligents, évolutifs jusqu'au niveau urbain.",
  "story_s1_details3": "Conçues pour fournir du chauffage à des milliers de personnes dans les grandes villes.",
  "story_s1_details4": "Des partenaires solides aident Qvantum à façonner la transition thermique en Europe.",
