  "story_s1_keyword4": "La collaboration comme accélérateur",
  "story_s1_subtitle": "Un avenir sans énergies fossiles pour tous, cela nécessite des systèmes énergétiques et des pompes à chaleur véritablement différents. Qvantum : une nouvelle ère énergétique.",
  "story_s1_title": "Notre vision",
  "story_s2_bullets_1_details": "Innovation et lancements sur le marché : une chaîne d'approvisionnement fiable comme stratégie",
  "story_s2_bullets_1_title": "Åstorp : innovation",
  "story_s2_bullets_2_details": "Évolutivité et haute efficacité : qualité et répétabilité",
  "story_s2_bullets_2_title": "Nyíregyháza : évolutivité",
  "story_s2_bullets_3_details": "Rapide, innovante et évolutive : grâce à cette structure organisationnelle et à ses deux sites, Qvantum peut agir rapidement et de manière innovante, tout en évoluant et en atteignant une efficacité et une productivité élevées.",
  "story_s2_bullets_3_title": "Ensemble : plus forts",
  "story_s2_fac1": "Åstorp, Suède",
