  "story_s3_subtitle": "avec des filiales au Royaume-Uni, en Allemagne, aux Pays-Bas, en Pologne, en Hongrie, en France et en Autriche.",
  "story_s3_title": "Nous sommes implantés ici",
  "story_s4_details1": "Conception de classe mondiale, développement basé sur les données et composants haut de gamme - conçus pour des performances optimales et une longue durée de vie.",
  "story_s4_details2": "Naturel, pérenne et sans exigences supplémentaires en matière de ventilation ; installation rapide et sans souci.",
  "story_s4_details3": "Charge la chaleur lorsque les prix de l'électricité (verte) sont bas et fournit lors des pics — le confort reste le même, les coûts et la charge du réseau diminuent.",
  "story_s4_details4": "Refroidissement là où la source le permet, avec des niveaux sonores très faibles ; eau courante hygiénique via un échangeur de chaleur.",
  "story_s4_details5": "Mises à jour logicielles à distance, diagnostic à distance et gestion de flotte, plus notre outil de conception pour une spécification rapide.",
  "story_s4_details6": "Basse température comme point de départ, s'intègre parfaitement aux réseaux (mini) sources ; faible impact sur le réseau.",
  "story_s4_details7": "Une plateforme standardisée pour une production efficace, une installation rapide, une maintenance facile et des prix de projet compétitifs.",
